{
  "tematica_1": {
    "texto": "O monitoramento das mudanças no uso e ocupação da terra e cobertura vegetal no espaço rural de Tumiritinga – MG, entre os anos de 1990 e 2020 na área compreendida pelas fazendas que deram origem aos assentamentos de reforma agrária do município, com destaque na antiga Fazenda Califórnia, que posteriormente originou os dois primeiros assentamentos estabelecidos: Primeiro de Junho e Cachoeirinha.",
    "evidencia": [
      "F3"
    ]
  },
  "tematica_2": {
    "texto": "A prática agropecuária monocultora e predatória esteve relacionada aos latifúndios, enquanto o Governo Federal promoveu o acesso democrático à terra a partir da criação gradual de cinco assentamentos no município após intensas manifestações de movimentos sociais.",
    "evidencia": [
      "F1",
      "F2"
    ]
  },
  "metodologias": [
    {
      "texto": "Imagens do satélite LANDSAT 5 (TM), para o ano de 1990, e LANDSAT 8 (OLI), para o ano de 2020.",
      "evidencia": [
        "F5"
      ]
    },
    {
      "texto": "Utilizou-se do software QGIS 2.18 para o processamento digital das imagens e a realização da classificação supervisionada foi realizada através do plugin SCP, presente no software.",
      "evidencia": [
        "F6"
      ]
    },
    {
      "texto": "Para a aferição da acurácia dos mapas temáticos, foi utilizado o plugin AcATaMa, onde foi escolhido o modelo da amostragem aleatória por extratos.",
      "evidencia": [
        "F7"
      ]
    },
    {
      "texto": "O mapeamento para o mês de fevereiro de 1990 revelou que a pastagem ocupava cerca de 4.051,89 ha (82,20%), o solo exposto ocupava uma área de 595,89 ha (12,09%), a vegetação densa ocupava 250,56 ha (5,08%), e as áreas com cultivos agrícolas ocupavam cerca de 24,66 ha (0,50%), comprovando o uso extensivo da terra, baixa tecnologia empregada e degradação ambiental naquele período.",
      "evidencia": [
        "F9"
      ]
    },
    {
      "texto": "O mapeamento para o mês de março de 2020 revelou que pastagem ocupava cerca de 3.298,52 ha (66,93%), o solo exposto abrangia uma área de 289,64 ha (5,88%), a vegetação densa ocupava cerca de 1.143,61 ha (23,20%), e a classe de cultivos agrícolas ocupava 143,77 ha (2,92%), evidenciando uma diminuição das áreas de pastagem e solo exposto, e um aumento das áreas de vegetação densa e cultivos agrícolas desde a consolidação dos assentamentos.",
      "evidencia": [
        "F10"
      ]
    }
  ]
}

